content.css:
.sp-host {
  position: relative;
  overflow: hidden;
  background: #0B0712;
}
.sp-error {
  position: absolute;
  left: 12px;
  bottom: 8px;
  color: #F28DB2;
  font: 13px "Segoe UI", Arial, sans-serif;
}
.sp-page {
  position: relative;
  box-sizing: border-box;
  width: 1920px;
  height: 1340px;
  padding: 20px 40px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  background: #0B0712;
  color: #F4ECFB;
  font-family: "Segoe UI", Arial, sans-serif;
  font-size: 16px;
}
.sp-page button {
  font-family: inherit;
}
.sp-row {
  display: flex;
  gap: 20px;
  min-height: 0;
}
.sp-card {
  box-sizing: border-box;
  background: #16101F;
  border: 1px solid #2E2340;
  border-radius: 18px;
  padding: 20px 26px;
  min-width: 0;
  overflow: hidden;
}
.sp-card-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}
.sp-card-title {
  font-size: 21px;
  font-weight: 700;
}
.sp-card-subtitle {
  margin-top: 2px;
  font-size: 14px;
  color: #8E80A0;
}
.sp-empty {
  padding: 40px 0;
  text-align: center;
  color: #8E80A0;
}
/* Header */
.sp-header {
  height: 112px;
  flex: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.sp-eyebrow {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 5px;
  text-transform: uppercase;
  color: #E0B0FF;
}
.sp-title {
  margin-top: 2px;
  font-size: 38px;
  font-weight: 700;
  letter-spacing: -0.5px;
}
.sp-header-right {
  text-align: right;
}
.sp-pill {
  display: inline-block;
  padding: 7px 18px;
  border: 1px solid rgba(224, 176, 255, 0.35);
  border-radius: 999px;
  background: rgba(224, 176, 255, 0.08);
  color: #E0B0FF;
  font-size: 16px;
  font-weight: 600;
  white-space: pre;
}
.sp-header-meta {
  margin-top: 6px;
  font-size: 14px;
  color: #8E80A0;
}
/* Download and email buttons, confirmation toast */
.sp-header-actions {
  display: flex;
  gap: 10px;
  margin-top: 10px;
}
.sp-action {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 36px;
  padding: 0 18px;
  border: 1px solid rgba(224, 176, 255, 0.45);
  border-radius: 10px;
  background: linear-gradient(135deg, rgba(224, 176, 255, 0.18), rgba(123, 79, 168, 0.22));
  color: #E0B0FF;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.3px;
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s, color 0.12s;
}
.sp-action:hover {
  border-color: #E0B0FF;
  background: #E0B0FF;
  color: #16101F;
}
.sp-action.sp-action-small {
  height: 38px;
  padding: 0 14px;
  font-size: 14px;
}
.sp-action.sp-busy,
.sp-action:disabled {
  opacity: 0.55;
  cursor: progress;
}
.sp-modal-backdrop {
  position: absolute;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 120px;
  background: rgba(5, 3, 8, 0.72);
  backdrop-filter: blur(3px);
}
.sp-modal {
  box-sizing: border-box;
  width: 620px;
  padding: 34px 38px 30px;
  border: 1px solid rgba(224, 176, 255, 0.4);
  border-radius: 22px;
  background: linear-gradient(160deg, #241A31 0%, #16101F 70%);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.6), 0 0 60px rgba(224, 176, 255, 0.12);
}
.sp-modal-icon {
  width: 56px;
  height: 56px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(224, 176, 255, 0.14);
  border: 1px solid rgba(224, 176, 255, 0.35);
  color: #E0B0FF;
  font-size: 28px;
  font-weight: 700;
}
.sp-modal-icon-success {
  background: rgba(189, 240, 214, 0.14);
  border-color: rgba(189, 240, 214, 0.5);
  color: #BDF0D6;
}
.sp-modal-icon-error {
  background: rgba(242, 141, 178, 0.14);
  border-color: rgba(242, 141, 178, 0.5);
  color: #F28DB2;
}
.sp-modal-title {
  margin-top: 20px;
  font-size: 26px;
  font-weight: 700;
  color: #F4ECFB;
}
.sp-modal-text {
  margin-top: 8px;
  font-size: 16px;
  line-height: 1.5;
  color: #A99BB8;
}
.sp-modal-details {
  margin: 18px 0 0;
  padding: 6px 18px;
  list-style: none;
  border: 1px solid rgba(224, 176, 255, 0.1);
  border-radius: 14px;
  background: rgba(11, 7, 18, 0.55);
}
.sp-modal-details li {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 9px 0;
  border-bottom: 1px solid rgba(224, 176, 255, 0.1);
  font-size: 15px;
}
.sp-modal-details li:last-child {
  border-bottom: none;
}
.sp-modal-label {
  flex: none;
  color: #8E80A0;
}
.sp-modal-value {
  min-width: 0;
  text-align: right;
  color: #E6DAF2;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sp-modal-actions {
  margin-top: 26px;
  display: flex;
  justify-content: flex-end;
  gap: 12px;
}
.sp-modal-actions button {
  height: 46px;
  padding: 0 24px;
  border-radius: 12px;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
}
.sp-modal-cancel {
  border: 1px solid rgba(224, 176, 255, 0.22);
  background: transparent;
  color: #E6DAF2;
}
.sp-modal-cancel:hover {
  border-color: #E0B0FF;
  color: #F4ECFB;
}
.sp-modal-confirm {
  border: 1px solid #E0B0FF;
  background: #E0B0FF;
  color: #16101F;
  box-shadow: 0 0 24px rgba(224, 176, 255, 0.35);
}
.sp-modal-confirm:hover {
  background: #EFD4FF;
}
.sp-modal-confirm:focus-visible {
  outline: 3px solid rgba(224, 176, 255, 0.45);
  outline-offset: 2px;
}
.sp-card-tools {
  display: flex;
  align-items: center;
  gap: 10px;
}
.sp-toast {
  position: absolute;
  right: 18px;
  bottom: 18px;
  z-index: 20;
  max-width: 420px;
  padding: 10px 16px;
  border: 1px solid rgba(189, 240, 214, 0.5);
  border-radius: 10px;
  background: #1E1629;
  color: #BDF0D6;
  font: 600 13px "Segoe UI", Arial, sans-serif;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
  opacity: 0;
  transform: translateY(8px);
  pointer-events: none;
  transition: opacity 0.2s, transform 0.2s;
}
.sp-toast.sp-toast-error {
  border-color: rgba(242, 141, 178, 0.55);
  color: #F28DB2;
}
.sp-toast.sp-toast-show {
  opacity: 1;
  transform: translateY(0);
}
/* Filter bar: Date range | Store | Category | actions, on one line */
.sp-filters {
  flex: none;
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr) minmax(0, 1fr) auto;
  align-items: end;
  gap: 28px;
  padding: 18px 26px 20px;
}
.sp-filter-cell {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}
.sp-filter-label {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #8E80A0;
}
.sp-date-row {
  display: flex;
  align-items: center;
  gap: 10px;
}
.sp-filter-sep {
  flex: none;
  color: #6F6380;
  font-size: 18px;
}
.sp-filter-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 46px;
}
.sp-date,
.sp-select {
  box-sizing: border-box;
  height: 46px;
  font: inherit;
  font-size: 16px;
  color: #F4ECFB;
  background-color: #1E1629;
  border: 1px solid rgba(224, 176, 255, 0.22);
  border-radius: 12px;
  padding: 0 14px;
  color-scheme: dark;
  outline: none;
  transition: border-color 0.12s, box-shadow 0.12s, background-color 0.12s;
}
.sp-date:hover,
.sp-select:hover {
  border-color: rgba(224, 176, 255, 0.45);
}
.sp-date:focus,
.sp-select:focus {
  border-color: #E0B0FF;
  box-shadow: 0 0 0 3px rgba(224, 176, 255, 0.16);
}
.sp-date.sp-select-active,
.sp-select.sp-select-active {
  border-color: #E0B0FF;
  background-color: rgba(224, 176, 255, 0.1);
}
.sp-date {
  flex: 1;
  min-width: 0;
}
.sp-select {
  width: 100%;
  padding-right: 42px;
  cursor: pointer;
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, #E0B0FF 50%), linear-gradient(135deg, #E0B0FF 50%, transparent 50%);
  background-position: calc(100% - 22px) 52%, calc(100% - 16px) 52%;
  background-size: 6px 6px;
  background-repeat: no-repeat;
}
.sp-select option {
  background: #1E1629;
  color: #F4ECFB;
}
.sp-select.sp-select-period {
  flex: none;
  width: 170px;
}
.sp-chip {
  --pill-color: #E0B0FF;
  padding: 5px 14px;
  border: 1px solid rgba(224, 176, 255, 0.22);
  border-radius: 999px;
  background: #1E1629;
  color: #E6DAF2;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.12s, color 0.12s, border-color 0.12s;
}
.sp-chip:hover {
  border-color: #E0B0FF;
  color: #F4ECFB;
}
.sp-chip.sp-chip-active {
  background: var(--pill-color);
  border-color: var(--pill-color);
  color: #16101F;
}
.sp-clear {
  height: 46px;
  padding: 0 20px;
  border: 1px solid rgba(242, 141, 178, 0.45);
  border-radius: 12px;
  white-space: nowrap;
  background: rgba(242, 141, 178, 0.1);
  color: #F28DB2;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.sp-clear:disabled {
  opacity: 0.35;
  cursor: default;
}
/* KPI cards */
.sp-kpis {
  flex: none;
  height: 168px;
}
.sp-kpi {
  position: relative;
  flex: 1;
  min-width: 0;
  box-sizing: border-box;
  padding: 24px 28px;
  border: 1px solid rgba(224, 176, 255, 0.14);
  border-radius: 18px;
  background: linear-gradient(135deg, #1E1629 0%, #15101D 100%);
  overflow: hidden;
}
.sp-kpi.sp-kpi-highlight {
  border-color: rgba(224, 176, 255, 0.55);
  background: linear-gradient(135deg, #3B2652 0%, #1C1428 75%);
}
.sp-kpi.sp-kpi-highlight .sp-kpi-value {
  color: #E0B0FF;
}
.sp-kpi-accent {
  position: absolute;
  top: 0;
  left: 28px;
  width: 54px;
  height: 4px;
  border-radius: 0 0 4px 4px;
  background: #E0B0FF;
}
.sp-kpi-label {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: #A99BB8;
}
.sp-kpi-value-row {
  margin-top: 8px;
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.sp-kpi-value {
  font-size: 46px;
  line-height: 52px;
  font-weight: 700;
  letter-spacing: -0.5px;
}
.sp-kpi-unit {
  font-size: 17px;
  font-weight: 600;
  color: #8E80A0;
}
.sp-kpi-note {
  margin-top: 6px;
  font-size: 15px;
  color: #8E80A0;
}
/* Middle row */
.sp-row-middle {
  flex: none;
  height: 400px;
}
.sp-months {
  flex: 0 0 1180px;
}
.sp-status {
  flex: 1;
}
.sp-card-total {
  text-align: right;
}
.sp-card-total-label {
  font-size: 13px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #8E80A0;
}
.sp-card-total-value {
  font-size: 24px;
  font-weight: 700;
  color: #E0B0FF;
}
.sp-month-plot {
  display: flex;
  gap: 28px;
  margin-top: 18px;
  padding: 0 16px;
}
.sp-month {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  border-radius: 14px;
  padding: 6px 0 8px;
  cursor: pointer;
  transition: background 0.12s;
}
.sp-month:hover {
  background: rgba(224, 176, 255, 0.05);
}
.sp-month.sp-month-active {
  background: rgba(224, 176, 255, 0.1);
  box-shadow: inset 0 0 0 1px rgba(224, 176, 255, 0.4);
}
.sp-month-bar-area {
  height: 200px;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  border-bottom: 1px solid rgba(224, 176, 255, 0.22);
  background-image: repeating-linear-gradient(to top, rgba(224, 176, 255, 0.06) 0 1px, transparent 1px 50px);
}
.sp-month-value {
  font-size: 18px;
  font-weight: 700;
}
.sp-month-bar {
  width: 48%;
  max-width: 170px;
  border-radius: 12px 12px 3px 3px;
  background: linear-gradient(180deg, #E0B0FF 0%, #9D6CCF 55%, #5B3B80 100%);
  box-shadow: 0 0 30px rgba(224, 176, 255, 0.22);
}
.sp-month-label {
  margin-top: 10px;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: #A99BB8;
}
.sp-month-sub {
  margin-top: 2px;
  font-size: 13px;
  color: #6F6380;
}
.sp-delta {
  margin-top: 6px;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
}
.sp-delta.sp-delta-up {
  color: #BDF0D6;
  background: rgba(189, 240, 214, 0.1);
}
.sp-delta.sp-delta-down {
  color: #F28DB2;
  background: rgba(242, 141, 178, 0.12);
}
.sp-delta.sp-delta-neutral {
  color: #6F6380;
}
.sp-status-body {
  display: flex;
  align-items: center;
  gap: 32px;
  margin-top: 26px;
}
.sp-donut {
  flex: none;
  width: 240px;
  height: 240px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 0 40px rgba(224, 176, 255, 0.18);
}
.sp-donut-hole {
  width: 162px;
  height: 162px;
  border-radius: 50%;
  background: #16101F;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.sp-donut-label {
  font-size: 13px;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: #8E80A0;
}
.sp-donut-value {
  font-size: 34px;
  font-weight: 700;
  color: #E0B0FF;
}
.sp-legend {
  flex: 1;
  min-width: 0;
}
.sp-legend-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 8px;
  border-bottom: 1px solid rgba(224, 176, 255, 0.1);
  border-radius: 8px;
  cursor: pointer;
}
.sp-legend-row:hover {
  background: rgba(224, 176, 255, 0.05);
}
.sp-legend-row.sp-legend-active {
  background: rgba(224, 176, 255, 0.12);
}
.sp-swatch {
  flex: none;
  width: 12px;
  height: 12px;
  border-radius: 3px;
}
.sp-legend-name {
  flex: 1;
  font-size: 16px;
  color: #E6DAF2;
}
.sp-legend-value {
  font-size: 16px;
  font-weight: 700;
}
.sp-legend-share {
  min-width: 54px;
  text-align: right;
  font-size: 14px;
  color: #8E80A0;
}
/* Bottom row */
.sp-row-bottom {
  flex: 1;
}
.sp-stores {
  flex: 0 0 900px;
}
.sp-products {
  flex: 1;
  display: flex;
  flex-direction: column;
}
.sp-store-list {
  margin-top: 12px;
}
.sp-store {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 10px 8px;
  border-radius: 10px;
  cursor: pointer;
}
.sp-store:hover {
  background: rgba(224, 176, 255, 0.05);
}
.sp-store.sp-store-active {
  background: rgba(224, 176, 255, 0.12);
}
.sp-store-name {
  flex: 0 0 250px;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  font-size: 16px;
  color: #E6DAF2;
  white-space: nowrap;
}
.sp-store-name.sp-store-unknown {
  color: #8E80A0;
}
.sp-badge {
  flex: none;
  padding: 1px 7px;
  border: 1px solid #F28DB2;
  border-radius: 4px;
  color: #F28DB2;
  font-size: 11px;
  letter-spacing: 1px;
}
.sp-track {
  flex: 1;
  height: 16px;
  border-radius: 999px;
  background: rgba(224, 176, 255, 0.07);
  overflow: hidden;
}
.sp-track.sp-track-small {
  height: 8px;
}
.sp-fill {
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, #7B4FA8, #E0B0FF);
}
.sp-fill.sp-fill-unknown {
  background: repeating-linear-gradient(45deg, #5D4A78 0 7px, #3E3052 7px 14px);
}
.sp-store-value {
  flex: 0 0 110px;
  text-align: right;
  font-size: 17px;
  font-weight: 700;
}
.sp-store-share {
  flex: 0 0 52px;
  text-align: right;
  font-size: 14px;
  color: #8E80A0;
}
.sp-search {
  width: 240px;
  font: inherit;
  font-size: 15px;
  color: #F4ECFB;
  background: #1E1629;
  border: 1px solid rgba(224, 176, 255, 0.22);
  border-radius: 10px;
  padding: 6px 12px;
  outline: none;
}
.sp-search::placeholder {
  color: #6F6380;
}
.sp-search:focus {
  border-color: #E0B0FF;
}
.sp-table-scroll {
  flex: 1;
  min-height: 0;
  margin-top: 12px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: #5D4A78 transparent;
}
.sp-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
}
.sp-table th {
  position: sticky;
  top: 0;
  background: #16101F;
  text-align: left;
  padding: 0 10px 10px;
  border-bottom: 1px solid rgba(224, 176, 255, 0.22);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: #8E80A0;
  cursor: pointer;
  white-space: nowrap;
  user-select: none;
}
.sp-table th:hover,
.sp-table th.sp-sorted {
  color: #E0B0FF;
}
.sp-table td {
  padding: 9px 10px;
  border-bottom: 1px solid rgba(224, 176, 255, 0.1);
  font-size: 16px;
  color: #E6DAF2;
  white-space: nowrap;
}
.sp-table .sp-num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.sp-product {
  font-weight: 600;
  color: #F4ECFB;
}
.sp-category {
  margin-top: 1px;
  font-size: 12px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #B48AE0;
}
.sp-muted {
  color: #A99BB8 !important;
}
.sp-net {
  font-weight: 700;
  color: #E0B0FF !important;
}
.sp-net.sp-zero {
  color: #F28DB2 !important;
}
.sp-share {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 200px;
}
.sp-share-value {
  min-width: 50px;
  text-align: right;
  font-size: 14px;
  color: #8E80A0;
}
.sp-table-count {
  margin-top: 8px;
  font-size: 13px;
  color: #8E80A0;
  text-align: right;
}
/* Neon glass theme, loaded after a visual's base styles. */
.sp-host {
  background: #060818;
}
.sp-page {
  color: #EEF2FF;
  transform-origin: 0 0;
  background: radial-gradient(760px 520px at 8% 2%, rgba(168, 85, 247, 0.3), transparent 70%), radial-gradient(820px 560px at 94% 12%, rgba(34, 211, 238, 0.2), transparent 70%), radial-gradient(900px 620px at 72% 98%, rgba(232, 121, 249, 0.18), transparent 70%), radial-gradient(760px 560px at 12% 92%, rgba(59, 130, 246, 0.22), transparent 70%), #060818;
}
/* Glass panels */
.sp-card {
  position: relative;
  border: 1px solid rgba(148, 163, 255, 0.2);
  border-radius: 20px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.02));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.1), 0 18px 40px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(22px) saturate(140%);
}
.sp-card-head {
  align-items: center;
}
.sp-card-title {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #EEF2FF;
}
.sp-card-title svg {
  color: #22D3EE;
  filter: drop-shadow(0 0 6px rgba(34, 211, 238, 0.7));
}
.sp-card-subtitle,
.sp-header-meta,
.sp-filter-label,
.sp-table-count,
.sp-card-total-label {
  color: #8B93B8;
}
.sp-eyebrow {
  color: #22D3EE;
  text-shadow: 0 0 12px rgba(34, 211, 238, 0.6);
}
.sp-title {
  background: linear-gradient(90deg, #FFFFFF, #C7D2FE 60%, #E879F9);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.sp-pill {
  border-color: rgba(34, 211, 238, 0.45);
  background: rgba(34, 211, 238, 0.1);
  color: #A5F3FC;
  box-shadow: 0 0 18px rgba(34, 211, 238, 0.18);
}
/* Buttons */
.sp-action {
  border-color: rgba(34, 211, 238, 0.5);
  background: rgba(34, 211, 238, 0.1);
  color: #A5F3FC;
  box-shadow: 0 0 14px rgba(34, 211, 238, 0.16);
}
.sp-action:hover {
  border-color: #22D3EE;
  background: #22D3EE;
  color: #06121C;
  box-shadow: 0 0 22px rgba(34, 211, 238, 0.6);
}
.sp-clear {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
/* Filters */
.sp-filter-label {
  display: flex;
  align-items: center;
  gap: 7px;
}
.sp-filter-label svg {
  color: #22D3EE;
}
.sp-date,
.sp-select,
.sp-search {
  background-color: rgba(255, 255, 255, 0.05);
  border-color: rgba(148, 163, 255, 0.24);
  color: #EEF2FF;
}
.sp-date:hover,
.sp-select:hover,
.sp-search:hover {
  border-color: rgba(34, 211, 238, 0.5);
}
.sp-date:focus,
.sp-select:focus,
.sp-search:focus {
  border-color: #22D3EE;
  box-shadow: 0 0 0 3px rgba(34, 211, 238, 0.18);
}
.sp-date.sp-select-active,
.sp-select.sp-select-active,
.sp-search.sp-select-active {
  border-color: #22D3EE;
  background-color: rgba(34, 211, 238, 0.12);
  box-shadow: 0 0 14px rgba(34, 211, 238, 0.22);
}
.sp-select {
  background-image: linear-gradient(45deg, transparent 50%, #22D3EE 50%), linear-gradient(135deg, #22D3EE 50%, transparent 50%);
}
.sp-select option {
  background: #141833;
  color: #EEF2FF;
}
/* KPI cards with a colored neon edge and a sparkline */
.sp-kpi,
.sp-kpi.sp-kpi-highlight {
  --glow: #22D3EE;
  --glow-soft: rgba(34, 211, 238, 0.32);
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 20px 24px;
  border: 1.5px solid var(--glow);
  border-radius: 20px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.09), rgba(255, 255, 255, 0.02));
  box-shadow: 0 0 22px var(--glow-soft), inset 0 0 26px rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(22px) saturate(140%);
  overflow: hidden;
}
.sp-kpi .sp-kpi-value,
.sp-kpi.sp-kpi-highlight .sp-kpi-value {
  color: #FFFFFF;
  text-shadow: 0 0 16px var(--glow-soft);
}
.sp-kpi.nx-magenta {
  --glow: #E879F9;
  --glow-soft: rgba(232, 121, 249, 0.32);
}
.sp-kpi.nx-blue {
  --glow: #3B82F6;
  --glow-soft: rgba(59, 130, 246, 0.38);
}
.sp-kpi.nx-violet {
  --glow: #A855F7;
  --glow-soft: rgba(168, 85, 247, 0.38);
}
.nx-kpi-text {
  min-width: 0;
}
.nx-kpi-side {
  flex: none;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: space-between;
  width: 170px;
}
.nx-kpi-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border: 1px solid var(--glow);
  border-radius: 12px;
  background: var(--glow-soft);
  color: #FFFFFF;
  box-shadow: 0 0 14px var(--glow-soft);
}
.nx-spark {
  width: 170px;
  height: 62px;
}
.sp-kpi-label {
  color: #C7D2FE;
  letter-spacing: 1.5px;
}
.sp-kpi-note,
.sp-kpi-unit {
  color: #8B93B8;
}
.sp-kpi-note {
  margin-top: 4px;
  line-height: 20px;
}
.nx-delta {
  display: block;
  color: #6EE7B7;
  font-weight: 700;
}
.nx-delta.nx-delta-down {
  color: #F472B6;
}
/* Charts */
.nx-chart {
  position: relative;
  width: 100%;
  min-height: 0;
}
.sp-months,
.sp-stores {
  display: flex;
  flex-direction: column;
}
.nx-grow {
  flex: 1;
}
.sp-card-total-value {
  color: #A5F3FC;
  text-shadow: 0 0 14px rgba(34, 211, 238, 0.5);
}
.nx-month-chips {
  display: flex;
  gap: 12px;
  flex: none;
  margin-top: 8px;
}
.sp-kpi-value-row {
  margin-top: 4px;
}
.sp-kpi .sp-kpi-value {
  font-size: 40px;
  line-height: 46px;
}
.nx-month-chip {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 14px;
  border: 1px solid rgba(148, 163, 255, 0.14);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
  cursor: pointer;
  transition: border-color 0.15s, box-shadow 0.15s, background 0.15s;
}
.nx-month-chip:hover,
.nx-month-chip.nx-active {
  border-color: #22D3EE;
  background: rgba(34, 211, 238, 0.1);
  box-shadow: 0 0 16px rgba(34, 211, 238, 0.25);
}
.nx-month-name {
  font-size: 14px;
  font-weight: 700;
  color: #EEF2FF;
}
.nx-month-sub {
  font-size: 12px;
  color: #8B93B8;
}
.nx-month-net {
  font-size: 16px;
  font-weight: 700;
  color: #A5F3FC;
  text-align: right;
}
.sp-delta {
  font-size: 12px;
}
.sp-delta.sp-delta-up {
  color: #6EE7B7;
  background: rgba(52, 211, 153, 0.12);
}
.sp-delta.sp-delta-down {
  color: #F472B6;
  background: rgba(244, 114, 182, 0.14);
}
.sp-delta.sp-delta-neutral {
  color: #8B93B8;
  padding-left: 0;
}
/* Donut */
.sp-status-body {
  margin-top: 14px;
}
.nx-donut {
  position: relative;
  flex: none;
  width: 270px;
  height: 270px;
}
.nx-donut-center {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}
.sp-donut-label {
  color: #8B93B8;
}
.sp-donut-value {
  color: #FFFFFF;
  text-shadow: 0 0 18px rgba(232, 121, 249, 0.7);
}
.sp-legend-row {
  border-bottom-color: rgba(148, 163, 255, 0.14);
}
.sp-legend-row:hover {
  background: rgba(34, 211, 238, 0.07);
}
.sp-legend-row.sp-legend-active {
  background: rgba(34, 211, 238, 0.14);
  box-shadow: inset 0 0 0 1px rgba(34, 211, 238, 0.5);
}
.sp-swatch {
  border-radius: 50%;
  box-shadow: 0 0 9px currentColor;
}
.sp-legend-name {
  color: #C7D2FE;
}
.sp-legend-share {
  color: #8B93B8;
}
/* Table */
.sp-table th {
  background: #131733;
  color: #8B93B8;
  border-bottom-color: rgba(148, 163, 255, 0.28);
}
.sp-table th:hover,
.sp-table th.sp-sorted {
  color: #22D3EE;
}
.sp-table td {
  border-bottom-color: rgba(148, 163, 255, 0.14);
  color: #C7D2FE;
}
.sp-table tbody tr {
  transition: background 0.12s;
}
.sp-table tbody tr:hover td {
  background: rgba(34, 211, 238, 0.07);
}
.sp-product {
  color: #EEF2FF;
}
.sp-category {
  color: #E879F9;
}
.sp-muted {
  color: #8B93B8 !important;
}
.sp-net {
  color: #A5F3FC !important;
}
.sp-net.sp-zero {
  color: #F472B6 !important;
}
.sp-share-value {
  color: #8B93B8;
}
.sp-track {
  background: rgba(148, 163, 255, 0.12);
}
.sp-fill {
  background: linear-gradient(90deg, #A855F7, #22D3EE);
  box-shadow: 0 0 10px rgba(34, 211, 238, 0.5);
  animation: nx-grow-x 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  transform-origin: left center;
}
@keyframes nx-grow-x {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}
.sp-table-scroll {
  scrollbar-color: rgba(34, 211, 238, 0.45) transparent;
}
/* Dialogs and toast */
.sp-modal {
  border-color: rgba(34, 211, 238, 0.45);
  background: linear-gradient(160deg, #1A1F45 0%, #0D1029 75%);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.65), 0 0 50px rgba(34, 211, 238, 0.2);
}
.sp-modal-icon {
  background: rgba(34, 211, 238, 0.14);
  border-color: rgba(34, 211, 238, 0.45);
  color: #22D3EE;
}
.sp-modal-icon.sp-modal-icon-success {
  background: rgba(52, 211, 153, 0.14);
  border-color: rgba(52, 211, 153, 0.5);
  color: #6EE7B7;
}
.sp-modal-icon.sp-modal-icon-error {
  background: rgba(244, 114, 182, 0.14);
  border-color: rgba(244, 114, 182, 0.5);
  color: #F472B6;
}
.sp-modal-text,
.sp-modal-label {
  color: #8B93B8;
}
.sp-modal-title {
  color: #EEF2FF;
}
.sp-modal-value {
  color: #C7D2FE;
}
.sp-modal-details {
  border-color: rgba(148, 163, 255, 0.14);
  background: rgba(6, 8, 24, 0.6);
}
.sp-modal-details li {
  border-bottom-color: rgba(148, 163, 255, 0.14);
}
.sp-modal-confirm {
  border-color: #22D3EE;
  background: #22D3EE;
  color: #06121C;
  box-shadow: 0 0 24px rgba(34, 211, 238, 0.45);
}
.sp-modal-confirm:hover {
  background: #67E8F9;
}
.sp-modal-cancel {
  border-color: rgba(148, 163, 255, 0.3);
  color: #C7D2FE;
}
.sp-modal-cancel:hover {
  border-color: #22D3EE;
  color: #EEF2FF;
}
